132	void PhysicsDebugDraw::endDraw()
133	{
134	    if (_drawNode == nullptr)
135	    {
136	        return;
137	    }
138	
139	    // nothing was requested for this frame, keep the node out of the render queue
140	    const bool anyOverlay = _config.drawShapes || _config.drawJoints || _config.drawContacts
141	        || _config.drawBoundingBoxes || _config.drawCentersOfMass || _config.drawVelocities
142	        || _config.drawSleepState;
143	
144	    _drawNode->setVisible(anyOverlay);
145	}
