445	void PhysicsDebugDraw::drawSegmentShape(const Vec2& a, const Vec2& b, float radius,
446	                                        const Color4F& color)
447	{
448	    if (_drawNode == nullptr)
449	    {
450	        return;
451	    }
452	
453	    if (radius > 0.0f)
454	    {
455	        _drawNode->drawSegment(a, b, radius, color);
456	    }
457	    else
458	    {
459	        _drawNode->drawLine(a, b, color);
