463	void PhysicsDebugDraw::drawBoundingBox(const Rect& bb, const Color4F& color)
464	{
465	    if (_drawNode == nullptr)
466	    {
467	        return;
468	    }
469	
470	    const Vec2 bottomLeft(bb.getMinX(), bb.getMinY());
471	    const Vec2 bottomRight(bb.getMaxX(), bb.getMinY());
472	    const Vec2 topRight(bb.getMaxX(), bb.getMaxY());
473	    const Vec2 topLeft(bb.getMinX(), bb.getMaxY());
474	
475	    _drawNode->drawRect(bottomLeft, bottomRight, topRight, topLeft, color);
476	}
