478	void PhysicsDebugDraw::drawContactPoint(const Vec2& point, const Vec2& normal, float depth,
479	                                        const Color4F& color)
480	{
481	    if (_drawNode == nullptr)
482	    {
483	        return;
484	    }
485	
486	    _drawNode->drawDot(point, kJointAnchorRadius, color);
487	
488	    if (normal.isZero())
489	    {
490	        return;
491	    }
492	
493	    const float length = std::max(std::fabs(depth), kContactNormalMinLength);
494	    _drawNode->drawLine(point, point + normal.getNormalized() * length, color);
495	}
