520	void PhysicsDebugDraw::drawCenterOfMass(const Vec2& pos, float radius, const Color4F& color)
521	{
522	    if (_drawNode == nullptr)
523	    {
524	        return;
525	    }
526	
527	    const float r = radius > 0.0f ? radius : kCenterOfMassRadius;
528	
529	    _drawNode->drawDot(pos, r, color);
530	    _drawNode->drawLine(pos - Vec2(r * 2.0f, 0.0f), pos + Vec2(r * 2.0f, 0.0f), color);
531	    _drawNode->drawLine(pos - Vec2(0.0f, r * 2.0f), pos + Vec2(0.0f, r * 2.0f), color);
532	}
