534	void PhysicsDebugDraw::drawSleepIndicator(const Vec2& pos, bool sleeping, const Color4F& color)
535	{
536	    if (_drawNode == nullptr)
537	    {
538	        return;
539	    }
540	
541	    if (sleeping)
542	    {
543	        _drawNode->drawDot(pos, kSleepIndicatorRadius, color);
544	    }
545	    else
546	    {
547	        _drawNode->drawCircle(pos, kSleepIndicatorRadius, 0.0f, kSleepIndicatorSegments, false, color);
548	    }
