563	void PhysicsDebugDraw::drawSpringJoint(const Vec2& anchorA, const Vec2& anchorB,
564	                                       float restLength, const Color4F& color)
565	{
566	    if (_drawNode == nullptr)
567	    {
568	        return;
569	    }
570	
571	    _drawNode->drawDot(anchorA, kJointAnchorRadius, color);
572	    _drawNode->drawDot(anchorB, kJointAnchorRadius, color);
573	
574	    const Vec2 delta = anchorB - anchorA;
575	    const float length = delta.getLength();
576	    if (length < kMinDrawLength)
577	    {
578	        return;
579	    }
580	
581	    const Vec2 dir = delta.getNormalized();
582	    const Vec2 side = dir.getPerp() * kSpringCoilWidth;
583	
584	    Vec2 previous = anchorA;
585	    for (int i = 1; i < kSpringCoilSegments; ++i)
586	    {
587	        const Vec2 onAxis = anchorA + dir * (length * static_cast<float>(i) / static_cast<float>(kSpringCoilSegments));
588	        const Vec2 next = (i % 2 == 0) ? onAxis - side : onAxis + side;
589	        _drawNode->drawLine(previous, next, color);
590	        previous = next;
591	    }
592	    _drawNode->drawLine(previous, anchorB, color);
593	
594	    if (restLength > 0.0f)
595	    {
596	        // where the spring would settle along its own axis
597	        _drawNode->drawDot(anchorA + dir * std::min(restLength, length), kJointRestMarkRadius, color);
598	    }
599	}
600	
601	void PhysicsDebugDraw::drawSlideJoint(const Vec2& anchorA, const Vec2& anchorB,
602	                                      float minDist, float maxDist, const Color4F& color)
603	{
604	    if (_drawNode == nullptr)
605	    {
606	        return;
607	    }
608	
609	    _drawNode->drawLine(anchorA, anchorB, color);
610	    _drawNode->drawDot(anchorA, kJointAnchorRadius, color);
611	    _drawNode->drawDot(anchorB, kJointAnchorRadius, color);
612	
613	    const Vec2 delta = anchorB - anchorA;
614	    const float length = delta.getLength();
615	    if (length < kMinDrawLength)
616	    {
617	        return;
618	    }
619	
620	    const Vec2 dir = delta.getNormalized();
621	    const Vec2 tick = dir.getPerp() * kJointLimitTickSize;
622	    const Vec2 minPoint = anchorA + dir * minDist;
623	    const Vec2 maxPoint = anchorA + dir * maxDist;
624	
625	    _drawNode->drawLine(minPoint - tick, minPoint + tick, color);
626	    _drawNode->drawLine(maxPoint - tick, maxPoint + tick, color);
627	}
