629	Color4F PhysicsDebugDraw::getShapeColor(PhysicsShape* shape) const
630	{
631	    if (shape == nullptr)
632	    {
633	        return _config.shapeColor;
634	    }
635	
636	    if (shape->isSensor())
637	    {
638	        const Color4F& base = _config.shapeColor;
639	        return Color4F(base.r, base.g, base.b, base.a * kSensorAlphaScale);
640	    }
641	
642	    return getBodyColor(shape->getBody());
643	}
644	
645	Color4F PhysicsDebugDraw::getBodyColor(PhysicsBody* body) const
646	{
647	    Color4F color = _config.shapeColor;
648	    if (body == nullptr)
649	    {
650	        return color;
651	    }
652	
653	    float intensity = 1.0f;
654	    if (body->isResting())
655	    {
656	        intensity = kRestingIntensity;
657	    }
658	    else if (!body->isDynamic())
659	    {
660	        intensity = kStaticIntensity;
661	    }
662	
663	    color.r *= intensity;
664	    color.g *= intensity;
665	    color.b *= intensity;
666	
667	    return color;
668	}
